    if (str == null || suffix == null) {
        return false;
    }

    int startPos = str.length() - suffix.length();
    if (startPos < 0) {
        return false;
    }

    String lowerCaseStr = ignoreCase ? str.toLowerCase() : str;
    String lowerCaseSuffix = ignoreCase ? suffix.toLowerCase() : suffix;
    return lowerCaseStr.substring(startPos).equals(lowerCaseSuffix);
}

