private void enlarge(final int size) {
    // Calculate the new minimum capacity needed to accommodate the additional 'size' bytes
    int newCapacity = size + getSize();

    // Check if the new capacity is larger than the current capacity
    if (newCapacity > getCapacity()) {
        // If the new capacity exceeds the maximum capacity, throw an exception
        if (newCapacity > getMaximumCapacity()) {
            throw new RuntimeException("Cannot enlarge byte vector beyond maximum capacity");
        }

        // Allocate a new byte array with the new capacity
        byte[] newArr = new byte[newCapacity];

        // Copy the existing bytes to the new array
        System.arraycopy(getData(), 0, newArr, 0, getSize());

        // Update the data and capacity variables
        data = newArr;
        capacity = newCapacity;
    }
}

