public long readLong(int offset) {
    long value = 0L;
    int readBytes = 0;
    while (readBytes < 8) {
        int currentByte = readByte(offset + readBytes);
        value |= ((long) currentByte & 0xFF) << (8 * readBytes);
        readBytes++;
    }
    return value;
}

