public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        // Put nullbytes into this byte vector
        for (int i = 0; i < byteLength; i++) {
            put(i, Byte.valueOf((byte) 0x00));
        }
    } else {
        // Copy bytes from the given array
        for (int i = byteOffset, j = 0; i < byteOffset + byteLength; i++, j++) {
            put(i, Byte.valueOf(byteArrayValue[j]));
        }
    }
    return this;
}

