    if (filename == null) {
        return -1;
    }

    // Get the last separator character
    int lastSeparatorIndex = filename.lastIndexOf(".");

    // If there is no dot, return -1
    if (lastSeparatorIndex == -1) {
        return -1;
    }

    // If there is a directory separator after the dot, return -1
    if (filename.lastIndexOf("/") > lastSeparatorIndex) {
        return -1;
    }

    // Otherwise, return the index of the last separator character
    return lastSeparatorIndex;
}

