public Character convertToType(Class<?> type, Object value) throws Exception {
    // Check if the input value is a character
    if (value instanceof Character) {
        return (Character) value;
    }

    // Check if the input value is a string
    if (value instanceof String) {
        String input = (String) value;
        if (input.length() == 1) {
            return input.charAt(0);
        }
    }

    // Check if the input value is a number
    if (value instanceof Number) {
        int input = ((Number) value).intValue();
        if (input >= Character.MIN_VALUE && input <= Character.MAX_VALUE) {
            return (char) input;
        }
    }

    // If none of the above conditions are met, throw an exception
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

