public static final <V> void reverse(V[] arr, int from, int to) {
    // Check if the input parameters are valid
    if (arr == null || from < 0 || to < from) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // If the range is empty, return immediately
    if (from == to) {
        return;
    }

    // Temporarily store the first element in the range
    V temp = arr[from];

    // Iterate through the range and swap the elements with the previous index
    for (int i = from; i < to; i++) {
        arr[i] = arr[i - 1];
    }

    // Set the first element of the range to the temporarily stored element
    arr[to] = temp;
}

