public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
	// First, we need to move all vertices from the bucket with label minLabel to the bucket with label 0
	for (Set<Integer> bucket : bucketsByLabel) {
		if (bucket.size() > 0 && !bucket.isEmpty()) {
			for (Integer vertex : bucket) {
				if (labels.get(vertex) == minLabel) {
					bucketsByLabel.get(0).add(vertex);
				}
			}
		}
	}

	// Then, we clear the bucket with label minLabel
	bucketsByLabel.get(minLabel).clear();

	// Finally, we update the labeling accordingly
	for (Integer vertex : labels) {
		if (labels.get(vertex) == minLabel) {
			labels.set(vertex, 0);
		}
	}
}

