private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize the result list and the sum variable
    List<Integer> suffixSumList = new ArrayList<>();
    long sum = 0;

    // Iterate from the end of the list to the beginning
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Add the current element to the sum
        sum += bounds.get(i);

        // Add the sum to the result list
        suffixSumList.add((int) sum);
    }

    // Return the computed suffix sum list and the sum of all elements
    return new Pair<>(suffixSumList, sum);
}

