public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Initialize the list of path segments
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Get the path component of the URI and remove leading '/' if necessary
    String path = u.getPath();
    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    // Split the path into individual path segments
    String[] segments = path.split("/");

    // Iterate over the path segments and decode them if necessary
    for (String segment : segments) {
        if (decode) {
            // Decode the path segment
            segment = URLDecoder.decode(segment, StandardCharsets.UTF_8.name());
        }
        // Add the decoded path segment to the list
        pathSegments.add(new PathSegmentImpl(segment));
    }

    return pathSegments;
}

