public static AtmosphereRequest wrap(HttpServletRequest request) {
    // Check for null input
    if (request == null) {
        throw new IllegalArgumentException("Request cannot be null");
    }

    // Check if request is already wrapped
    if (request instanceof AtmosphereRequest) {
        return (AtmosphereRequest) request;
    }

    // Create a new AtmosphereRequest and wrap the HttpServletRequest
    AtmosphereRequest atmosphereRequest = new AtmosphereRequest(request);

    // Set the request parameters and attributes
    atmosphereRequest.setParameters(request.getParameterMap());
    atmosphereRequest.setAttributes(request.getAttributeMap());

    // Set the request headers
    Map<String, String> headers = new HashMap<>();
    Enumeration<String> headerNames = request.getHeaderNames();
    while (headerNames.hasMoreElements()) {
        String name = headerNames.nextElement();
        headers.put(name, request.getHeader(name));
    }
    atmosphereRequest.setHeaders(headers);

    // Set the request content
    atmosphereRequest.setContent(request.getInputStream());

    // Return the wrapped AtmosphereRequest
    return atmosphereRequest;
}

