public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {

    try {

        // Check that the index is within the bounds of the original string
        if (index >= str.length() || index < 0) {
            return false;
        }

        // Check that the substring is not longer than the original string
        if (substring.length() > str.length() - index) {
            return false;
        }

        // Check that all characters in the substring match with the characters in the original string
        for (int i = 0; i < substring.length(); i++) {
            if (str.charAt(index + i) != substring.charAt(i)) {
                return false;
            }
        }

        return true;

    } catch (Exception e) {
        e.printStackTrace();
        return false;
    }
}

