List<SequenceRange> buildSequenceRanges() {
  // Steps

  1. Extract list of current profiles
  2. Create a list of founder profiles
  3. Calculate the number of segments
  4. Create a list of randomly generated segment indices
  5. Create a list of sequence ranges using the indices and number of segments

  // Extract list of current profiles
  List<Profile> currentProfiles = ProfileManager.getAllProfiles();

  // Create a list of founder profiles
  List<Profile> founderProfiles = new ArrayList<>();
  List<Integer> founderIndices = new ArrayList<>();
  for (int i = 0; i < currentProfiles.size(); i++) {
    founderProfiles.add(currentProfiles.get(i));
  }

  int numSegments = founderProfiles.size();

  // Generate randomly assigned segment indices
  List<Integer> randomIndices = new ArrayList<>();
  for (int i = 0; i < numSegments; i++) {
    randomIndices.add(i);
  }
  Collections.shuffle(randomIndices);

  // Generate sequence ranges using the indices and number of segments
  List<SequenceRange> sequenceRanges = new ArrayList<>();
  for (int i = 0; i < numSegments; i++) {
    int startIndex = randomIndices.get(i);
    int endIndex = numSegments - i - 1;
    sequenceRanges.add(new SequenceRange(startIndex, endIndex));
  }

  return sequenceRanges;
}

