public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }

    // Find the next prime number that is greater than or equal to desiredCapacity
    int prime = 2;
    while (prime < desiredCapacity) {
        prime++;
        if (isPrime(prime)) {
            return prime;
        }
    }

    // If the desired capacity is at least 1000, allow for 11% growth
    if (desiredCapacity >= 1000) {
        double growthFactor = 1.11;
        double desiredCapacityDbl = (double) desiredCapacity;
        double growth = growthFactor * desiredCapacityDbl;
        return (int) Math.round(growth);
    } else {
        return desiredCapacity;
    }
}

