public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Check for null inputs
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Null input detected");
    }

    // Use the LinkedBuffer to write the message to the stream
    int size = schema.calculateSize(message);
    byte[] messageData = new byte[size];
    LinkedBuffer.writeTo(message, messageData, schema, buffer);
    out.write(messageData);

    // Write the length of the message to the stream
    int messageSize = messageData.length;
    out.writeInt(messageSize);

    // Return the size of the message
    return messageSize;
}

