public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {

    // Validate input
    if (out == null) {
        throw new IllegalArgumentException("DataOutput cannot be null");
    }
    if (node == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    // Write content size
    int contentSize = 0;
    out.writeInt(contentSize);

    // Write buffer content
    for (byte[] bytes : node.getNode()) {
        out.write(bytes);
        contentSize += bytes.length;
    }

    return contentSize;
}

